  const select = (id, label, rows, value) => `<label class="lb" for="${id}">${label}</label><select id="${id}">${rows.map(([k, text]) => `<option value="${e(k)}" ${String(k) === String(value) ? 'selected' : ''}>${e(text)}</option>`).join('')}</select>`;
  const card = (title, body) => `<section class="card"><h2>${title}</h2>${body}</section>`;
  const badge = text => `<span class="tag">${e(text)}</span>`;
  const eventList = rows => rows.length ? `<ol>${rows.map(x => `<li>${e(x.time || '')} · ${e(x.text || '')}</li>`).join('')}</ol>` : '<p class="d">还没有处置记录。</p>';
  function roleHeader() { return card('当前合成管理身份', `<p class="d">${e(actor().name)} · ${e(actor().label)}。只操作本档案的模拟实体，不授予真实管理权限。</p>${select('pw-actor', '切换演示职责', roles.map(r => [r.id, r.name + ' · ' + r.label]), state.actor)}${button('切换身份', 'actor')}${link('管理总览', 'admin')}`); }
  function managed(title, body) { load(); return card(title, '<p class="d">静态演示 · 拟真数据 · 本机管理预览</p>') + (flash ? `<p class="fb no" role="alert">${e(flash)}</p>` : '') + (!state.authenticated ? card('先进入合成管理身份', link('管理登录', 'alogin')) : roleHeader() + body()); }
  function future(title, body) { load(); return card(title, '<p class="d">未来阶段 · 合成流程预览。使用原创文本与合成身份；不连接模型、RTC、未成年人或支付服务，不采集真实资料。</p>' + (!state.future ? button('明确开启本机合成预览', 'future') : button('关闭合成预览', 'future-off', '', false, 'ghost'))) + (state.future ? body() : card('预览边界', '<p>成人学习主线不受影响。开启后可演示完整流程及失败恢复，关闭后停止未完成模拟。</p>')); }
