  function contentInfo(c) { return `<p>${e(c.title)} · v${c.version} ${badge(c.status)}</p><p class="d">作者 ${e(c.author)} · 初审 ${e(c.l1 || '未签')} · 终审 ${e(c.l2 || '未签')} · 当前发布 ${c.published ? 'v' + c.published : '无'}</p>`; }
  V.alogin = () => { load(); return card('进入合成管理预览', '<p class="d">请选择拟真职责。合成密码仅作表单演示，不保存，也不是正式登录。</p>' + select('pw-login-actor', '合成身份', roles.map(r => [r.id, r.name + ' · ' + r.label]), state.actor) + input('pw-login-name', '合成账号', scenarioInfo?.mode === 'empty' ? '' : 'preview@test.invalid') + input('pw-login-password', '演示密码', '', 'password') + button('进入本机管理工作台', 'login') + link('回演示工具', 'lab')); };
  V.admin = () => managed('管理工作台', () => card('当前存量与待办', `<p>当前发布 ${state.content.filter(c => c.published && !c.blocked.includes(c.published)).length} 条 · 待审 ${state.content.filter(c => ['待初审', '待终审'].includes(c.status)).length} 条 · 未结工单 ${state.tickets.filter(t => t.status !== '已关闭').length} 张</p><p class="d">范围：本账号合成实体；数据版本 ${state.revision}，不把存量当作今日新增。</p>`) + card('处理业务', [['建稿送审', 'adraft'], ['双人审核', 'areview'], ['发布与强停', 'apublish'], ['治理案件', 'agov'], ['媒体管理', 'amedia'], ['客服工单', 'acs'], ['订单退款', 'ashop'], ['举报分诊', 'areport'], ['审计追溯', 'aaudit'], ['运行恢复', 'aobs'], ['权限范围', 'aperm']].map(([t, r]) => link(t, r)).join('')));
  V.aperm = () => managed('权限只读', () => card('当前角色获准范围', `<p>${e(actor().label)}</p><ul>${actor().scopes.map(s => `<li>${e(s)}</li>`).join('')}</ul><p class="d">此页只读，没有授权写入按钮。审核与财务操作由不同合成人员执行。</p>`));
  V.adraft = () => managed('建稿与送审', () => { const c = content(); return card('内容版本', contentChooser() + contentInfo(c)) + card('编辑草稿', input('pw-title', '内容标题', c.title) + select('pw-type', '内容类型', ['阅读', '语法', '词汇'].map(t => [t, t]), c.type) + area('pw-text', '原创正文', c.text) + '<label class="lb"><input id="pw-rights" type="checkbox" ' + (c.rights ? 'checked' : '') + '> 原创或已取得合成授权</label><label class="lb"><input id="pw-media-ok" type="checkbox" ' + (c.media ? 'checked' : '') + '> 必要媒体已通过合成校验</label>' + button('新建草稿', 'content-new') + button('创建本内容的新版本', 'content-revise', '', !['已发布', '已下架', '强制下架'].includes(c.status)) + button('保存本版本', 'content-save', '', !c.id || c.status !== '草稿') + button('提交初审', 'content-submit', '', !c.id || c.status !== '草稿') + eventList(c.events)); });
  V.areview = () => managed('不同人员两级审核', () => { const c = content(); return card('待审内容', contentChooser() + contentInfo(c) + `<p class="writing-copy">${e(c.text)}</p>`) + card('审核决定', area('pw-review-reason', '审核结论或退回原因（必填）') + button('初审通过', 'review1', '', c.status !== '待初审') + button('终审通过', 'review2', '', c.status !== '待终审') + button('退回修改', 'review-return', '', !['待初审', '待终审'].includes(c.status), 'ghost') + '<p class="d">作者不能自审；终审不能与初审同人。审批通过后仍须单独发布。</p>' + eventList(c.events)); });
