  V.agov = () => managed('治理与风险处置', () => card('当前案件', !state.risks.length ? '<p>当前没有合成风险案件。举报建档后会形成待分诊案件。</p>' + link('去举报分诊', 'areport') : state.risks.map(r => `<article><h3>${e(r.id)} · ${e(r.title)}</h3>${badge(r.status)}<p class="d">来源 ${e(r.source)} · 接收方 ${e(r.target || '未升级')}</p>${area('pw-risk-reason-' + r.id, '处置原因（必填）', r.reason)}${select('pw-risk-target-' + r.id, '授权接收方', roles.filter(r => r.scopes.includes('governance') || r.scopes.includes('support')).map(r => [r.id, r.name]), r.target)}${button('建档受理', 'risk-claim', r.id, r.status !== '待分诊')}${button('隔离', 'risk-isolate', r.id, r.owner !== state.actor || !['处理中', '已隔离'].includes(r.status))}${button('发起升级', 'risk-escalate', r.id, r.owner !== state.actor || !['处理中', '已隔离'].includes(r.status))}${button('接收升级', 'risk-accept', r.id, r.status !== '升级待接收')}${button('关闭案件', 'risk-close', r.id, ['待分诊', '升级待接收', '已关闭'].includes(r.status))}${eventList(r.events)}</article>`).join('')));
