  V.acs = () => managed('工单接收与闭环', () => { const t = ticket(); return card('新增合成工单', input('pw-ticket-title', '合成工单标题') + area('pw-ticket-body', '安全合成问题说明') + button('生成一张本机合成工单', 'ticket-new')) + card('工单查询', select('pw-ticket', '选择工单', state.tickets.map(t => [t.id, t.id + ' · ' + t.title + ' · ' + t.status]), selectedTicket) + button('查看工单', 'ticket-select', '', !state.tickets.length)) + (!t.id ? card('当前没有工单', '<p>没有待处理或历史工单。可用上方表单创建一张合成工单后体验流转。</p>') : card(e(t.title), `<p>${e(t.learner)} ${badge(t.status)} · 版本 ${t.version}</p><p class="d">负责人 ${e(t.assignee || '未接单')} · 接收方 ${e(t.target || '无')}</p>${t.safe ? t.messages.map(m => `<p><b>${e(m.who)}</b>：${e(m.text)}</p>`).join('') : '<p class="fb no">历史记录只有引用，安全预览信息不足，不能假回复或关闭；可升级补正。</p>'}` + area('pw-ticket-text', '回复或处置原因（必填）') + select('pw-ticket-target', '授权升级接收方', roles.filter(r => r.scopes.includes('support')).map(r => [r.id, r.name + ' · ' + r.label]), t.target) + button('接单', 'ticket-claim', '', t.status !== '待接单') + button('回复学员', 'ticket-reply', '', !t.safe || t.assignee !== state.actor || ['已关闭', '升级待接收'].includes(t.status)) + button('发起升级', 'ticket-escalate', '', ['已关闭', '升级待接收'].includes(t.status)) + button('接收升级', 'ticket-accept', '', t.status !== '升级待接收' || t.target !== state.actor) + button('确认已解决', 'ticket-resolve', '', !t.safe || t.assignee !== state.actor || !['处理中', '等待学员'].includes(t.status)) + button('关闭已解决工单', 'ticket-close', '', t.status !== '已解决') + button('重开工单', 'ticket-reopen', '', t.status !== '已关闭') + eventList(t.events))); });
  V.ashop = () => managed('订单与退款双审', () => { const o = order(), r = state.refunds.find(r => r.id === o.refund); return card('本人合成订单', select('pw-order', '选择订单', state.orders.map(o => [o.id, o.title + ' · ' + o.payment]), selectedOrder) + button('查看订单', 'order-select', '', !state.orders.length) + button('生成一笔合成已支付订单', 'order-new') + `<p>${e(o.id)} · ¥${o.amount}</p><p>资金 ${e(o.payment)} · 权益 ${e(o.entitlement)} · 续订 ${o.renewal ? '下期自动续订样例' : '无自动续订'}</p>${badge(o.receipt)}`) + (!o.id ? card('当前没有订单', '<p>此合成场景没有资金或权益事实，可先生成样例订单。不发生真实付款。</p>') : card('退款与票据', area('pw-refund-reason', '申请或审核原因（必填）') + button('创建退款申请', 'refund-new', '', o.payment !== '已支付' || !!r) + (r ? `<p>${e(r.id)} ${badge(r.status)} · 审核人 ${e(r.approvals.join('、') || '未审')}</p>${button('退款初审', 'refund1', '', r.status !== '待初审')}${button('退款终审', 'refund2', '', r.status !== '待终审')}${button('审核退回', 'refund-return', '', !['待初审', '待终审'].includes(r.status))}${button('补正并重新送审', 'refund-resubmit', '', r.status !== '已退回' || r.applicant !== state.actor)}${button('模拟原路退款失败', 'refund-fail', '', r.status !== '待渠道处理')}${button('执行拟真退款并读回权益', 'refund-execute', '', !['待渠道处理', '渠道失败'].includes(r.status))}` : '') + button('取消下次续订', 'renew-cancel', '', !o.renewal) + button('申请合成电子收据', 'receipt', '', o.receipt !== '未申请') + '<p class="d">两个不同合成人员独立审批；终审后仍等待渠道处理，不提前显示退款到账。</p>')); });
  V.areport = () => managed('举报分诊队列', () => card('安全预览', !state.reports.length ? '<p>没有待分诊举报，也没有未处理队列。不将空列表解释为加载失败。</p>' : state.reports.map(r => `<article><h3>${e(r.id)} · ${e(r.title)}</h3>${badge(r.status)}<p>${e(r.detail)}</p>${input('pw-report-reason-' + r.id, '分诊原因')}${button('核实并建立案件', 'report-case', r.id, !!r.risk)}${r.risk ? `<p class="d">关联 ${e(r.risk)}</p>${link('查看治理案件', 'agov')}` : ''}</article>`).join('')));
