  V.voice = () => future('语音场景合成体验', () => card('场景与示范', select('pw-voice-scene', '练习场景', ['跟读', '复述', '角色扮演'].map(s => [s, s]), state.voice.scene) + `<p>${e(state.voiceSamples[0].text)}</p><p class="d">使用浏览器文本示范；模拟记录不打开麦克风，不保存录音。</p>` + button('播放文本示范', 'voice-speak') + badge(state.voice.phase) + button('开始合成练习', 'voice-start', '', state.voice.phase === 'practicing') + button('完成并读取样例评分', 'voice-complete', '', state.voice.phase !== 'practicing') + button('模拟失败', 'voice-fail', '', state.voice.phase !== 'practicing') + button('重试本轮', 'voice-start', '', state.voice.phase !== 'failed') + link('评分与历史', 'vscore')));
